def gcd(a: int, b: int) -> int:
    """Return the greatest common divisor of two non‑negative integers."""
    # Handle the case where both inputs are zero: gcd(0,0) is defined as 0 here.
    if a == 0:
        return b
    if b == 0:
        return a

    while b:
        a, b = b, a % b
    return a
